// Harder, integrity-protected eval battery for the autoresearch loop.
// These tasks use tight turn budgets and stress harness affordances: edit
// uniqueness with distractors, large-file/observation truncation, multi-file
// coordination, iterative debugging, and precise structured edits.
// Do not edit this file from the loop.
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { join } from 'node:path';

async function w(dir, rel, content) {
  const full = join(dir, rel);
  await mkdir(join(full, '..'), { recursive: true });
  await writeFile(full, content, 'utf8');
}

async function readMaybe(dir, rel) {
  try { return await readFile(join(dir, rel), 'utf8'); } catch { return null; }
}

async function runsClean(dir, cmd, execFileP) {
  try { await execFileP('bash', ['-lc', cmd], { cwd: dir }); return true; } catch { return false; }
}

function functionBody(text, name) {
  const start = text.indexOf(`function ${name}`);
  if (start === -1) return '';
  const brace = text.indexOf('{', start);
  if (brace === -1) return '';
  let depth = 0;
  for (let i = brace; i < text.length; i++) {
    if (text[i] === '{') depth++;
    else if (text[i] === '}') { depth--; if (depth === 0) return text.slice(brace, i + 1); }
  }
  return '';
}

export const TASKS = [
  {
    name: 'unique_edit_distractor',
    maxTurns: 6,
    prompt:
      'src/state.js defines three functions alpha, beta, and gamma, each containing a line `const limit = 10;`. Change the limit to 25 ONLY inside function beta. Leave alpha and gamma exactly as they are.',
    async setup(dir) {
      const fn = (name) => `export function ${name}() {\n  const limit = 10;\n  return limit;\n}\n`;
      await w(dir, 'src/state.js', `${fn('alpha')}\n${fn('beta')}\n${fn('gamma')}\n`);
    },
    async grade(dir) {
      const text = await readMaybe(dir, 'src/state.js');
      if (text === null) return false;
      return /const limit = 25;/.test(functionBody(text, 'beta'))
        && /const limit = 10;/.test(functionBody(text, 'alpha'))
        && /const limit = 10;/.test(functionBody(text, 'gamma'))
        && (text.match(/const limit = 25;/g) || []).length === 1;
    },
  },
  {
    name: 'large_file_grep_edit',
    maxTurns: 7,
    prompt:
      'src/big.js is a large generated file. Somewhere in it is a line `export const SECRET_TOKEN = "PLACEHOLDER";`. Replace PLACEHOLDER with resolved-42 (so the value becomes "resolved-42"). Change nothing else. Hint: search for the marker rather than reading the whole file.',
    async setup(dir) {
      const lines = [];
      for (let i = 0; i < 1500; i++) lines.push(`export const FILLER_${i} = ${i}; // padding line ${i} lorem ipsum dolor sit amet`);
      lines.splice(900, 0, 'export const SECRET_TOKEN = "PLACEHOLDER";');
      await w(dir, 'src/big.js', lines.join('\n') + '\n');
    },
    async grade(dir) {
      const text = await readMaybe(dir, 'src/big.js');
      if (text === null) return false;
      return text.includes('export const SECRET_TOKEN = "resolved-42";') && !text.includes('PLACEHOLDER');
    },
  },
  {
    name: 'multi_file_rename',
    maxTurns: 9,
    prompt:
      "Rename the function `calc` to `computeDouble` everywhere it appears in src/ (its definition, the import, and the call site) so that `npm test` still passes. After renaming, the identifier `calc` must not appear anywhere under src/.",
    async setup(dir) {
      await w(dir, 'package.json', JSON.stringify({ name: 'e', type: 'module', scripts: { test: 'node --test test/*.test.js' } }) + '\n');
      await w(dir, 'src/util.js', 'export function calc(a) {\n  return a * 2;\n}\n');
      await w(dir, 'src/use.js', "import { calc } from './util.js';\nexport const run = (x) => calc(x) + 1;\n");
      await w(dir, 'test/use.test.js', "import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { run } from '../src/use.js';\ntest('run', () => { assert.equal(run(3), 7); });\n");
    },
    async grade(dir, execFileP) {
      const testsPass = await runsClean(dir, 'npm test', execFileP);
      const util = await readMaybe(dir, 'src/util.js');
      const use = await readMaybe(dir, 'src/use.js');
      if (util === null || use === null) return false;
      const noCalc = !/\bcalc\b/.test(util) && !/\bcalc\b/.test(use);
      return testsPass && noCalc;
    },
  },
  {
    name: 'iterative_two_bugs',
    maxTurns: 8,
    prompt:
      "src/mathx.js has two bugs: sub() and mul() both return the wrong result. Fix both so 'npm test' passes. Do not edit test files.",
    async setup(dir) {
      await w(dir, 'package.json', JSON.stringify({ name: 'e', type: 'module', scripts: { test: 'node --test test/*.test.js' } }) + '\n');
      await w(dir, 'src/mathx.js', 'export function sub(a, b) {\n  return a + b;\n}\nexport function mul(a, b) {\n  return a + b;\n}\n');
      await w(dir, 'test/mathx.test.js', "import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { sub, mul } from '../src/mathx.js';\ntest('math', () => { assert.equal(sub(5,3),2); assert.equal(mul(4,3),12); });\n");
    },
    async grade(dir, execFileP) {
      return runsClean(dir, 'npm test', execFileP);
    },
  },
  {
    name: 'implement_from_marker',
    maxTurns: 7,
    prompt:
      'src/parse.js exports toInt(s) with an // IMPLEMENT marker. Implement it so toInt("42") === 42, toInt("x") === 0, and toInt("") === 0. Run npm test to verify. Do not edit test files.',
    async setup(dir) {
      await w(dir, 'package.json', JSON.stringify({ name: 'e', type: 'module', scripts: { test: 'node --test test/*.test.js' } }) + '\n');
      await w(dir, 'src/parse.js', 'export function toInt(s) {\n  // IMPLEMENT: parse a decimal string to an integer; return 0 for invalid or empty input\n}\n');
      await w(dir, 'test/parse.test.js', "import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { toInt } from '../src/parse.js';\ntest('toInt', () => { assert.equal(toInt('42'),42); assert.equal(toInt('x'),0); assert.equal(toInt(''),0); });\n");
    },
    async grade(dir, execFileP) {
      return runsClean(dir, 'npm test', execFileP);
    },
  },
  {
    name: 'recall_after_masking',
    maxTurns: 12,
    prompt:
      'Do these steps in order. 1) Read src/base.txt and note the integer it contains. 2) Then read each of src/f0.txt, src/f1.txt, src/f2.txt, src/f3.txt, src/f4.txt, src/f5.txt, src/f6.txt in order. 3) Finally, write result.txt containing exactly the integer equal to (the number from src/base.txt) + (the number from src/f5.txt), with no other text.',
    async setup(dir) {
      await w(dir, 'src/base.txt', '100\n');
      const vals = [7, 11, 13, 17, 19, 23, 29];
      for (let i = 0; i < vals.length; i++) await w(dir, `src/f${i}.txt`, `${vals[i]}\n`);
    },
    async grade(dir) {
      const text = await readMaybe(dir, 'result.txt');
      if (text === null) return false;
      return text.trim() === String(100 + 23); // base + f5
    },
  },
  {
    name: 'wide_refactor_with_distractor',
    maxTurns: 12,
    prompt:
      "Rename the function `handle` to `process` across every file in src/ (definition, imports, and all call sites) so that `npm test` still passes. Do NOT touch the unrelated variable named `handler`. After the change, the standalone identifier `handle` must not appear under src/, but `handler` must remain.",
    async setup(dir) {
      await w(dir, 'package.json', JSON.stringify({ name: 'e', type: 'module', scripts: { test: 'node --test test/*.test.js' } }) + '\n');
      await w(dir, 'src/core.js', 'export function handle(x) {\n  return x + 1;\n}\n');
      await w(dir, 'src/a.js', "import { handle } from './core.js';\nexport const a = (n) => handle(n) * 2;\n");
      await w(dir, 'src/b.js', "import { handle } from './core.js';\nconst handler = 'noop';\nexport const b = (n) => handle(n) + (handler === 'noop' ? 0 : 1);\n");
      await w(dir, 'src/c.js', "import { a } from './a.js';\nimport { b } from './b.js';\nexport const c = (n) => a(n) + b(n);\n");
      await w(dir, 'test/c.test.js', "import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { c } from '../src/c.js';\ntest('c', () => { assert.equal(c(2), (3*2) + 3); });\n");
    },
    async grade(dir, execFileP) {
      const testsPass = await runsClean(dir, 'npm test', execFileP);
      const files = ['src/core.js', 'src/a.js', 'src/b.js', 'src/c.js'];
      let hasHandler = false;
      for (const rel of files) {
        const text = await readMaybe(dir, rel);
        if (text === null) return false;
        if (/\bhandle\b/.test(text)) return false;
        if (/\bhandler\b/.test(text)) hasHandler = true;
      }
      return testsPass && hasHandler;
    },
  },
  {
    name: 'json_deep_update',
    maxTurns: 6,
    prompt:
      'Update config.json: set server.tls.enabled to true and server.port to 9090. Leave every other field (including name) unchanged. Keep it valid JSON.',
    async setup(dir) {
      await w(dir, 'config.json', JSON.stringify({ name: 'svc', server: { port: 8080, tls: { enabled: false, ca: 'root' } }, retries: 3 }, null, 2) + '\n');
    },
    async grade(dir) {
      const text = await readMaybe(dir, 'config.json');
      if (text === null) return false;
      let obj;
      try { obj = JSON.parse(text); } catch { return false; }
      return obj?.server?.tls?.enabled === true
        && obj?.server?.port === 9090
        && obj?.server?.tls?.ca === 'root'
        && obj?.name === 'svc'
        && obj?.retries === 3;
    },
  },
];
